package vn.edu.hcmute.example3; import java.math.BigDecimal; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; @Configuration class DataInitializer {@Bean CommandLineRunner seed(UserRepository users,ProductRepository products,PasswordEncoder e){return a->{if(users.count()==0){var admin=users.save(new AppUser("admin","admin@gocsach.vn",e.encode("123456"),"Lê Trọng Bảo","ADMIN",true));var user=users.save(new AppUser("user","user@gocsach.vn",e.encode("123456"),"Bạn đọc Góc Sách","USER",true));products.save(new Product("Dế Mèn Phiêu Lưu Ký","Tác phẩm thiếu nhi của Tô Hoài",new BigDecimal("85000"),"https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=600",user));products.save(new Product("Nhà Giả Kim","Tiểu thuyết của Paulo Coelho",new BigDecimal("79000"),"https://images.unsplash.com/photo-1543002588-bfa74002ed7e?w=600",admin));}};}}
